        target = b + (node.module.split(".") if node.module else [])
    else:
        if node.module and node.module.startswith("tally"):
            out.append(("EXTERNAL-TALLY", node.module))
        return out
    for a in node.names:
        cand = ".".join(target + [a.name])
        if cand in mods:
            out.append(("mod", cand))
        else:
            tn = ".".join(target)
            out.append(("mod", tn))
    return out


graph = {}
for m, p in mods.items():
    tree = ast.parse(open(p, encoding="utf-8").read())
    graph[m] = set()
    for node in ast.walk(tree):
        if isinstance(node, (ast.Import, ast.ImportFrom)):
            for kind, t in resolve(m, node):
                if kind == "EXTERNAL-TALLY":
                    print("EXTERNAL", m, t)
                    continue
                graph[m].add(t)
                if t not in mods:
